import (
	"context"
	"fmt"
	"log"
)

response, err := client.Communications().SendEmail(context.Background(), map[string]any{
	"invoice": "INV-0001",
	"to":      []any{"jane@example.com"},
	"subject": "Your invoice",
	"body":    "Hello Jane, here is your invoice.",
}, nil)
if err != nil {
	log.Fatal(err)
}
fmt.Println(response.Map)
